import{c as t,Q as n,j as r,m as o}from"./chunks/framework.BqPkuuVc.js";const p=JSON.parse('{"title":"Radio punches","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/radio-punches.md","filePath":"user/running-the-event/radio-punches.md"}'),a={name:"user/running-the-event/radio-punches.md"};function s(i,e,h,d,c,u){return n(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="radio-punches" tabindex="-1">Radio punches <a class="header-anchor" href="#radio-punches" aria-label="Permalink to &quot;Radio punches&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators monitoring the live feed of punches coming in from radio controls.</p><p>A <strong>radio punch</strong> is a punch that reaches Manager <em>live</em> as a competitor passes a control, rather than waiting for their card to be downloaded at the finish. The punch travels from a <strong>meshO Control</strong> unit to <strong>meshO Prime</strong>, over USB into Manager — or it can arrive over the network from an upstream system (see <a href="#forwarding-and-receiving-punches">Forwarding and receiving punches</a>). Either way it appears within seconds on the dashboard, the Leaderboard, Commentary, Tracking and Live View.</p><p>This page is about the <strong>Radio Punches</strong> view, where you watch the raw feed and act on it. For setting up the hardware, see <a href="./connecting-prime-and-radios">Connecting meshO Prime and radios</a>.</p><h2 id="the-radio-punches-view" tabindex="-1">The Radio Punches view <a class="header-anchor" href="#the-radio-punches-view" aria-label="Permalink to &quot;The Radio Punches view&quot;">​</a></h2><p>Open <strong>Radio Punches</strong> from the live section of the event navigation. (It only appears once <strong>meshO Prime</strong> or <strong>Accept SIRAP Punches</strong> is enabled for the event, and the event is running.) If neither source is on, the page explains how to enable one.</p><p>Each punch is a row, <strong>newest first</strong>:</p><table tabindex="0"><thead><tr><th>Column</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Card Number</strong></td><td>The card number that punched.</td></tr><tr><td><strong>Name</strong></td><td>The competitor that card belongs to. Click it to open their record.</td></tr><tr><td><strong>Control</strong></td><td>The control code that was punched.</td></tr><tr><td><strong>Punch Time</strong></td><td>The time of the punch.</td></tr><tr><td><strong>Channel</strong></td><td>Which of the meshO Control&#39;s two radios took the punch: <strong>Red</strong> or <strong>Blue</strong>.</td></tr><tr><td><strong>Sent by</strong></td><td>Whether the competitor&#39;s <strong>SIAC</strong> sent the punch, or the <strong>SRR station</strong> they punched.</td></tr><tr><td><strong>Copies heard</strong></td><td>How many copies of the punch the Control&#39;s radios heard, damaged ones included, up to the one it took. <strong>1</strong> means the first copy it heard was clean; <strong>15+</strong> means fifteen or more.</td></tr><tr><td><strong>Signal (dBm)</strong></td><td>How strong that copy was. Around −40 is right beside the Control; below about −90 the copies start arriving damaged.</td></tr><tr><td><strong>Frequency offset (kHz)</strong></td><td>How far the transmitter was from the Control&#39;s own frequency.</td></tr></tbody></table><p>The last five say <a href="#how-a-punch-was-received">how the punch was received</a>, and are blank for some punches.</p><p>The list is always sorted by punch time (most recent at the top) and you can&#39;t re-sort it — it&#39;s a live feed. To find a particular punch, use the filters at the top: <strong>Search Card</strong>, <strong>Search Name</strong>, and the <strong>Control</strong> dropdown to show just one control.</p><h3 id="unknown-cards" tabindex="-1">Unknown cards <a class="header-anchor" href="#unknown-cards" aria-label="Permalink to &quot;Unknown cards&quot;">​</a></h3><p>If a card that punches isn&#39;t matched to a competitor in the event, its <strong>Name</strong> shows as <strong>Unknown</strong> — or, if the card is recognised in the <a href="./../reference/competitor-registry">Competitor Registry</a>, the person&#39;s name appears <strong>in brackets</strong>. Click it to <strong>add a competitor for that card</strong> on the spot, so their punches start counting.</p><h3 id="rebuilt-punches" tabindex="-1">Rebuilt punches <a class="header-anchor" href="#rebuilt-punches" aria-label="Permalink to &quot;Rebuilt punches&quot;">​</a></h3><p>A meshO Control unit sometimes hears a card only in damaged radio copies. Rather than lose the punch, it rebuilds it from those copies, and a punch rebuilt that way is marked <strong>Rebuilt</strong> beside its card number.</p><p>A rebuilt punch is usually right, but it can be wrong in a way nothing else shows: its card number can belong to a different card from the one that punched. So until an undamaged copy of the same punch arrives and confirms it — at which point the mark disappears:</p><ul><li><strong>On a card that isn&#39;t entered</strong>, it is treated as damaged rather than as an unknown runner. It isn&#39;t counted as an unknown card anywhere — not on the dashboard, in the in-forest and pending lists, or when you finish the event. It still appears in this list, marked.</li><li><strong>It is never passed on to other timing software.</strong> meshO Prime keeps it off the connection MeOS and similar programs read, and Manager holds it back from <a href="#forwarding-and-receiving-punches">forwarding</a> until it is confirmed.</li></ul><p>A rebuilt punch on an entered competitor&#39;s card counts like any other, and the card download at the finish still settles the result.</p><p>Rebuilt punches are marked only with meshO Control 3.2.6 and meshO Prime 3.2.4 or later. An older Control sends them as ordinary punches; an older Prime drops them, so with a new Control and an old Prime they never reach Manager.</p><h3 id="how-a-punch-was-received" tabindex="-1">How a punch was received <a class="header-anchor" href="#how-a-punch-was-received" aria-label="Permalink to &quot;How a punch was received&quot;">​</a></h3><p>From meshO Control 4.0.0, every punch says how the Control received it: the <strong>Channel</strong>, <strong>Sent by</strong>, <strong>Copies heard</strong>, <strong>Signal</strong> and <strong>Frequency offset</strong> columns. They help you place Controls and find cards and stations that are hard to hear:</p><ul><li><strong>Many copies heard</strong>, or a weak <strong>Signal</strong>, at one Control means its radios struggle to hear that spot. A Control closer to the station, or higher up, will hear the first copy.</li><li><strong>Copies heard</strong> counts only copies the radios heard. A copy sent while the runner was out of range is not counted, because only the card knows it was sent.</li><li><strong>Frequency offset</strong> is measured against the Control&#39;s own frequency, so compare one card across one Control rather than across several. A card or station far from the rest at every Control is drifting; Controls tune themselves to the cards they hear, so most cards sit near zero.</li></ul><p>The columns are blank for punches from a Control older than 4.0.0, punches received from another system over SIRAP, and punches entered by hand. Hide any you don&#39;t need with the column menu at the end of the header row.</p><p><strong>meshO Control 4.0.0 needs meshO Prime 4.0.0.</strong> An older Prime drops every punch from a 4.0.0 Control, so update Prime first.</p><h2 id="suppressing-a-stray-punch" tabindex="-1">Suppressing a stray punch <a class="header-anchor" href="#suppressing-a-stray-punch" aria-label="Permalink to &quot;Suppressing a stray punch&quot;">​</a></h2><p>A bad or duplicate punch (a unit double-reporting, someone testing a control) is handled on the <strong>competitor</strong>, not in this list. Open the competitor, go to their <strong>Radio Punches</strong> tab, and <strong>suppress</strong> the punch — it&#39;s kept but greyed out and struck through, so it no longer affects the result and you can see what you did. <strong>Reinstate</strong> it the same way if you change your mind. See <a href="./resolving-issues">Resolving issues on the day</a>.</p><p>Late and duplicate punches are otherwise handled automatically: punches are processed in time order per competitor, and a punch Manager already has is ignored rather than counted twice.</p><h2 id="recovering-missed-punches" tabindex="-1">Recovering missed punches <a class="header-anchor" href="#recovering-missed-punches" aria-label="Permalink to &quot;Recovering missed punches&quot;">​</a></h2><p>If Prime was connected for some time before the event was started, those punches will not have reached Manager — but they&#39;re still in Prime&#39;s memory. From the Radio Punches view&#39;s actions menu, choose <strong>Resend stored punches</strong>:</p><blockquote><p><em>meshO Prime will resend every punch that is still in its memory. Duplicate punches will be ignored.</em></p></blockquote><p>Prime replays its whole memory and Manager fills in anything it missed, skipping what it already has. (This is available while the event is in progress and Prime is the punch source.)</p><h2 id="forwarding-and-receiving-punches" tabindex="-1">Forwarding and receiving punches <a class="header-anchor" href="#forwarding-and-receiving-punches" aria-label="Permalink to &quot;Forwarding and receiving punches&quot;">​</a></h2><p>Manager can pass radio punches to and from other systems over the network:</p><ul><li><strong>Forwarding (outbound)</strong> — send every punch on to a downstream system as it arrives, except a <a href="#rebuilt-punches">rebuilt punch</a>, which waits until it is confirmed. Turn on <strong>Forward Radio Punches</strong> on the event&#39;s <strong>Radio Controls</strong> tab, and set the destination <strong>host</strong>, <strong>port</strong> and <strong>protocol</strong> (SIRAP or OE12) in <a href="./../reference/settings">Settings</a>. The dashboard&#39;s <strong>Radio Punch Forwarding</strong> card shows <strong>Active</strong> / <strong>Disabled</strong> with running <strong>Sent</strong> and <strong>Queued</strong> counts.</li><li><strong>Receiving (inbound, SIRAP)</strong> — accept punches from an upstream system. Turn on <strong>Accept SIRAP Punches</strong> for the event and set the listening <strong>port</strong> in Settings. The dashboard&#39;s <strong>SIRAP Punch Listening</strong> card shows <strong>Listening</strong> / <strong>Stopped</strong> and a <strong>Received</strong> count, which starts again from zero each time an event starts accepting punches — so it counts the event you are running, not everything since Manager was opened. Punches that arrive this way appear in the Radio Punches list just like Prime&#39;s.</li></ul><p>Forwarding and receiving are independent — you can do either, both, or neither.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./connecting-prime-and-radios">Connecting meshO Prime and radios</a> — the hardware behind the feed</li><li><a href="./../event-setup/controls-and-radio-controls">Controls and radio controls</a> — control codes and the Start/Finish/Check codes</li><li><a href="./tracking">Tracking</a> and <a href="./live-view">Live view</a> — the spatial view of the same data</li><li><a href="./station-memory">Station Memory</a> — recovering punches a control never sent</li></ul>',36)])])}const l=t(a,[["render",s]]);export{p as __pageData,l as default};
